#include <Servo.h>// Библиотека, позволяющая управлять сервоприводами

//10-13 строки отвечают за вывод данных в монитор порта с Датчика расстояния
#define SENSORCLASSIC
#ifndef SENSORCLASSIC
#include <NewPing.h> //Библиотека, позволяющая управлять ультразвуковыми датчиками расстояния
#endif

const int LED = 13;// Пин, к которому подключен встроенный светодиод в ARDUINO NANO

//18-20 строки: пины, к которым подключены провода для управления левым мотором
const int enA = 11; 
const int in1 = 10;
const int in2 = 9;

//23-25 строки: пины, к которым подключены провода для управления правым мотором
const int in3 = 8; 
const int in4 = 7;
const int enB = 6;

//28-29 строки: параметры скорости
const int velSlow = 150; // Медленная езда
const int velFast = 255; // Быстрая езда

Servo servo;// Создаем объект типа Servo

const int servPin = 5; //Пин, к которому подключен сервопривод

const int servOffset = -14;//Калибровка сервопривода

//38-42 строки:положения сервопривода
const int dirLeft2 = 160;
const int dirLeft1 = 110;
const int dirAhead = 90;
const int dirRight1 = 70;
const int dirRight2 = 20;

//45-47 строки: группы положений сервопривода
const int servDirs1[3] = {dirLeft2, dirRight2, dirLeft2};
const int servDirs2[4] = {dirLeft1, dirAhead, dirRight1, dirAhead};
const int servDirs3[6] = {dirLeft2, dirLeft1, dirAhead, dirRight1, dirRight2, dirAhead};

//50-51 строки: пины, к которым подключены ввод и вывод с датчика расстояния HC-SR04
const int triggerPin = 3;
const int echoPin = 2;

//54-57 строки: назначаем параметры датчика расстояния
#ifndef SENSORCLASSIC
const int maxDistPing=500;// Максимальная дистанция замера
NewPing sonar(triggerPin, echoPin, maxDistPing);//Ввод параметров датчика расстояния
#endif

//60-62 строки: расстояния для разных поведений робота
const long stopDist = 30;  // Стоп
const long drivDist = 50;  // Медленная езда
const long fastDist = 80;  // Быстрая езда

//65-70 строки: логические переменные
bool forward = false;
bool backward = false;
bool fast = false;
bool slow = false;
int servoPos = 0;
int m = 0;

//73-84 строки: Функция, предназначенная для активации медленной езды для двух двигателей
void drive_slow() {
    if (!slow) {//функция выполняется только при условии, что переменная slow=false
        analogWrite(enA, velSlow);//мощность левого мотора
        analogWrite(enB, velSlow);//мощность правого мотора
        fast = false;  // Установка режима быстрого движения в false
        slow = true; // Установка режима медленного движения в true
        //80-82 строки: вывод в монитор порта фразы "Медленная езда"
        #ifdef SERIAL
            Serial.write("--> Медленная езда\n");
        #endif
    }
}

//87-98 строки: функция, предназначенная для активации быстрой езды для двух двигателей
void drive_fast() {
    if (!fast) {//функция выполняется только при условии, что переменная fast=false
        analogWrite(enA, velFast);//мощность левого мотора
        analogWrite(enB, velFast);//мощность правого мотора
        fast = true; // Установка режима быстрого движения в true
        slow = false; // Установка режима медленного движения в false
        //94-96 строки: вывод в монитор порта фразы "Быстрая езда"
        #ifdef SERIAL
            Serial.write("--> Быстрая езда\n");
        #endif
    }
}

//101-116 строки: Функция, отвечающая за управление двигателями робота таким образом, чтобы он начал движение вперед
void drive_forward() {
    if (!forward) {//функция выполняется только при условии, что переменная forward=false
        motors_off();//функция остановки двигателей робота
        delay(100); // Задержка для стабильности работы
        digitalWrite(in1, LOW);//настройка левого мотора
        digitalWrite(in2, HIGH);//настройка левого мотора
        digitalWrite(in3, HIGH);//настройка правого мотора
        digitalWrite(in4, LOW);//настройка правого мотора
        forward = true; // Устанавливаем режим движения вперед
        backward = false; // Отключаем режим движения назад
        //112-114 строки: вывод в монитор порта фразы "Вперед"
        #ifdef SERIAL
            Serial.write("--> Вперед\n");
        #endif
    }
}

//119-134 строки: Функция, отвечающая за управление двигателями робота таким образом, чтобы он начал движение назад
void drive_backward() {
    if (!backward) {//функция выполняется только при условии, что переменная backward=false
        motors_off();//функция остановки двигателей робота
        delay(100); // Задержка для стабильности работы
        digitalWrite(in1, HIGH);//настройка левого мотора
        digitalWrite(in2, LOW);//настройка левого мотора
        digitalWrite(in3, LOW);//настройка правого мотора
        digitalWrite(in4, HIGH);//настройка правого мотора
        forward = false;  // Отключаем режим движения вперед
        backward = true; // Устанавливаем режим движения назад
        //129-132 строки: вывод в монитор порта фразы "Назад"
        #ifdef SERIAL
            Serial.write("--> Назад\n");
        #endif
    }
}

//137-141 строки: функция остановки робота при движении вперед
void drive_forward_stop(int dt) {
    drive_forward(); // Запускаем функцию движения робота вперед
    delay(dt); // Задержка на величину dt
    motors_off(); // Функция для остановки двигателей робота
}

//144-148 строки: функция остановки робота при движении назад
void drive_backward_stop(int dt) {
    drive_backward(); // Запускаем функцию движения робота назад
    delay(dt); // Задержка на величину dt
    motors_off(); // Функция для остановки двигателей робота
}

//151-162 строки: функция остановки двигателей робота
void motors_off() {
    digitalWrite(in1, LOW);//настройка левого мотора
    digitalWrite(in2, LOW);//настройка левого мотора
    digitalWrite(in3, LOW);//настройка правого мотора
    digitalWrite(in4, LOW);//настройка правого мотора
    forward = false; // Отключаем режим движения вперед
    backward = false; // Отключаем режим движения назад
     //159-161 строки: вывод в монитор порта фразы "Стоп"
    #ifdef SERIAL
        Serial.write("--> Стоп\n");
    #endif
}

//165-174 строки: функция поворота робота влево
void turn_left() {
    digitalWrite(in1, HIGH);//настройка левого мотора
    digitalWrite(in2, LOW);//настройка левого мотора
    digitalWrite(in3, HIGH);//настройка правого мотора
    digitalWrite(in4, LOW);//настройка правого мотора
    //171-173 строки: вывод в монитор порта фразы "Влево"
    #ifdef SERIAL
        Serial.write("--> Влево\n");
    #endif
}

//177-186 строки: функция поворота робота вправо
void turn_right() {
    digitalWrite(in1, LOW);//настройка левого мотора
    digitalWrite(in2, HIGH);//настройка левого мотора
    digitalWrite(in3, LOW);//настройка правого мотора
    digitalWrite(in4, HIGH);//настройка правого мотора
    //183-185 строки: вывод в монитор порта фразы "Вправо"
    #ifdef SERIAL
        Serial.write("--> Вправо\n");
    #endif
}

//190-197 строки: функция, предназначенная для осуществления поворота робота влево 
//на определённое время, и последующей остановки его
void turn_left_stop(int dt) {
    motors_off(); // Остановка всех двигателей
    delay(100); // Задержка в 100 миллисекунд для стабильности перед началом движения
    drive_fast(); // Запуск функции, отвечающей за быструю езду
    turn_left(); // Запуск функции, отвечающей за поворот влево
    delay(dt); // Задержка на величину dt
    motors_off(); // Остановка всех двигателей после завершения поворота
}

//201-208 строки: функция, предназначенная для осуществления поворота робота вправо 
//на определённое время, и последующей остановки его
void turn_right_stop(int dt) {
    motors_off(); // Остановка всех двигателей
    delay(100); // Задержка в 100 миллисекунд для стабильности перед началом движения
    drive_fast(); // Запуск функции, отвечающей за быструю езду
    turn_right(); // Запуск функции, отвечающей за поворот вправо
    delay(dt); // Задержка на величину dt
    motors_off(); // Остановка всех двигателей после завершения поворота
}

//211-217 строки: функция, отвечающая за поворот сервопривода к новой заданной позиции
void servo_dir(int newPos) {
    int diff = 0; // Переменная для хранения разницы между текущей и новой позицией
    servo.write(newPos + servOffset);  // Перемещение сервопривода в заданную новую позицию с учетом смещения
    diff = abs(newPos - servoPos); // Вычисление абсолютной разницы между новой и текущей позицией
    servoPos = newPos; // Обновление текущей позиции сервопривода на новую
    delay(4*diff + 50); // Задержка для завершения перемещения
}

//220-234 строки: функция, предназначенная для измерения расстояния с использованием ультразвукового датчика расстояния
#ifdef SENSORCLASSIC
long get_distance_classic(){
    long time = 0; // Переменная для хранения времени прохождения звукового сигнала
    const unsigned long timeOut = 50000; // Максимальное время ожидания (в микросекундах)
    digitalWrite(triggerPin, LOW); // Убедимся, что сигнал на триггере низкий
    delayMicroseconds(5); // Ждать 5 микросекунд
    noInterrupts(); // Отключаем прерывания
    digitalWrite(triggerPin, HIGH); // Установить триггер в HIGH, чтобы отправить ультразвуковой сигнал
    delayMicroseconds(10); // Сигнал должен быть высоким 10 мс
    digitalWrite(triggerPin, LOW); // Установить триггер в LOW
    time = pulseIn(echoPin, HIGH, timeOut); // Измерение времени возвращения сигнала от датчика
    interrupts();  // Включаем прерывания
    return(time / 58.2); // Конвертация времени в сантиметры и возврат
}
#endif

//238-260 строки: функция, предназначенная для управления сервоприводом, считывания расстояния с 
//ультразвукового датчика и вывода значений в монитор порта
int get_distance_dir(int servoDir) {
    long distance = 0; // Инициализация переменной для хранения расстояния
    servo_dir(servoDir); // Перемещение сервопривода в указанную позицию
     //242-246 строки: вывод в монитор порта фразы "Угол: x градусов"
    #ifdef SERIAL
        Serial.write("Угол: ");
        Serial.print(servoDir, DEC);
        Serial.write(" градусов\n");
    #endif
    //248-252 строки: получение расстояния
    #ifdef SENSORCLASSIC
        distance = get_distance_classic(); // Получение расстояния с ультразвукового датчика (классический)
    #else
        distance = sonar.ping_cm(); // Использование другого метода (из библиотеки NewPing.h)
    #endif
    //254-258 строки: вывод в монитор порта фразы "Дистанция: y см"
    #ifdef SERIAL
        Serial.write("Дистанция: ");
        Serial.print(distance, DEC);
        Serial.write(" см\n");
    #endif
    return(distance); // Возврат измеренного расстояния
}

//265-274 строки: функция для определения минимального расстояния до препятствия
int get_mindist_ahead() {
    long distance = 0; // Переменная для хранения текущего расстояния
    long minDist = 2147483647; // Инициализация переменной для хранения минимального расстояния
    for (int i = 0; i < 4; i++) {
        distance = get_distance_dir(servDirs2[i]);  // Получение расстояния для заданного направления серво
        if (distance < minDist) minDist = distance; // Обновление минимального расстояния
        delay(200);   // Задержка между измерениями (200 мс)
    }
    return minDist; // Возврат минимального расстояния
}

//278-304 строки: функция для определения максимальной дистанции до препятствия
int get_maxdir_around() {
    long distance = 0; // Переменная для хранения текущего расстояния
    long maxDist = 0; // Инициализация максимального расстояния
    int newDir = -1; // Инициализация переменной для хранения направления с максимальным расстоянием
    int rn = 0;  // Переменная для хранения случайного числа (0 или 1)
    //284-286 строки: вывод в монитор порта фразы "Идет поиск (влево/вправо):"
    #ifdef SERIAL
        Serial.write("--> Идет поиск (влево/вправо):\n");
    #endif
    rn = random(2);  // Генерация случайной величины (0 или 1)
    //289-295 строки: цикл для проверки двух направлений
    for (int i = rn; i < 2+rn; i++) {
        distance = get_distance_dir(servDirs1[i]); // Получение расстояния для текущего направления
        if (distance > maxDist) { // Если текущее расстояние больше максимального
            maxDist = distance; // Обновить максимальное расстояние
            newDir = servDirs1[i]; // Запомнить направление
        }
    }
    servo_dir(dirAhead); // Возврат сервопривода в первоначальное положение
     //298-302 строки: вывод результата в монитор порта
    #ifdef SERIAL
        Serial.write("--> Максимальная дистанция: ");
        Serial.print(newDir, DEC);
        Serial.write(" градусов\n");
    #endif
    return(newDir);  // Возврат направления с максимальной дистанцией
}

void setup() {
  pinMode(LED, OUTPUT);
  for (int i = 0; i < 3; i++) {
    digitalWrite(LED, HIGH);
    delay(500);
    digitalWrite(LED, LOW);
    delay(250);
  }
  pinMode(enA, OUTPUT);
  pinMode(in1, OUTPUT);
  pinMode(in2, OUTPUT);
  pinMode(in3, OUTPUT);
  pinMode(in4, OUTPUT);
  pinMode(enB, OUTPUT);
  delay(20);
  motors_off();
  servo.attach(servPin);
  delay(20);
  servoPos = dirAhead;
  servo_dir(dirAhead);
  delay(500);
  for (int i = 0; i < 6; i++) {
      servo_dir(servDirs3[i]);
  }
  #ifdef SENSORCLASSIC
      pinMode(triggerPin, OUTPUT);
      pinMode(echoPin, INPUT);
      delay(20);
      digitalWrite(triggerPin, HIGH);
  #endif
  #ifdef SERIAL
      Serial.begin(9600);
  #endif
  randomSeed(analogRead(0));
  drive_slow();
  drive_forward();
}

void loop() {
    long distance = 0;
    int newDir = dirAhead;
    int n = 0;
    int randNumber = 0;
    m++;
    if (m > 12) m = 0;
    randNumber = random(300);
    #ifdef SERIAL
      Serial.write("Рандомное число: ");
      Serial.print(randNumber, DEC);
      Serial.write("\n");
    #endif
    switch (randNumber) {
      case 22:
        motors_off();
        delay(500);
        break;
      case 33:
        turn_right_stop(1200);
        drive_forward();
        break; 
      case 44:
        turn_left_stop(1200);
        drive_forward();
        break;  
      case 99:
        drive_forward();
        break;
      default:
        break;
    }
    if (forward){
        switch (m){
          case 10:
              distance = get_distance_dir(dirLeft1);
              break;
          case 12:
              distance = get_distance_dir(dirRight1);
              break;
          default:
             distance = get_distance_dir(dirAhead); 
             break;
        }
    }
    else {
       distance = get_distance_dir(dirAhead);  
    }
    if (distance <= stopDist) {
        if (!backward) {
            drive_backward_stop(250);
            while (distance <= drivDist && n < 3) {
              n++;
              newDir = get_maxdir_around();
              if (newDir < dirAhead) {
                  turn_right_stop(400);
               } else {
                  turn_left_stop(400);
               }
               delay(200);
               distance = get_distance_dir(dirAhead);
            }
            if (n == 3) {
                if (newDir < dirAhead) {
                  turn_right_stop(800);
                } else {
                  turn_left_stop(800);
                }
            }
        }
        drive_forward();
    }
    if (distance >= fastDist) {
        drive_fast();
    } else {
        drive_slow();
    }
}
